//! rustc's builtin attribute parsers, as data: for each attribute its path, what a second one
//! on the same node does, whether it must be written `unsafe(..)`, what it may be applied to,
//! and its template (the forms "valid forms for the attribute are ..." lists).
//!
//! Generated by reading every parser of `compiler/rustc_attr_parsing/src/attributes/`
//! (`SingleAttributeParser`, `NoArgsAttributeParser`, `CombineAttributeParser`: their `PATH`,
//! `ON_DUPLICATE`, `SAFETY`, `ALLOWED_TARGETS`, `TEMPLATE`), and the parsers that implement
//! `AttributeParser` themselves written by hand; `compiler/rustc_attr_parsing/src/
//! target_checking.rs` (`Policy`, `AllowedTargets`), `template.rs` (`AttributeTemplate`,
//! `template!`) and `attributes/mod.rs` (`OnDuplicate`, `AttributeSafety`) (MIT or
//! Apache-2.0).

pub(crate) mod index;

use span::Edition;

use super::target::{GenericParamKind, MethodKind, Target};
use Policy::{Allow, AllowSilent, Error, Warn};

/// What attribute parsing does with an attribute on a target: rustc's `Policy`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Policy {
    Allow(Target),
    /// Allowed, and not named among the targets it can be applied to.
    AllowSilent(Target),
    /// `unused_attributes` (or `misplaced_diagnostic_attributes`), "previously accepted".
    Warn(Target),
    /// An error (`diagnostics-items`' `checks/attrs.rs`).
    Error(Target),
}

/// rustc's `AllowedTargets`.
#[derive(Clone, Copy, Debug)]
pub(crate) enum Targets {
    /// What is not listed is an error.
    AllowList(&'static [Policy]),
    /// What is not listed is a warning.
    AllowListWarnRest(&'static [Policy]),
    /// The parser checks the target itself, by its arguments (`repr`).
    ManuallyChecked,
}

/// What rustc does with an attribute's target: `AllowedResult`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Allowed {
    Allowed,
    Warn,
    Error,
}

impl Targets {
    /// rustc's `AllowedTargets::is_allowed`.
    pub(crate) fn is_allowed(self, target: Target) -> Allowed {
        let has = |list: &[Policy], policy: fn(Target) -> Policy| list.contains(&policy(target));
        match self {
            Targets::AllowList(list) => match () {
                _ if has(list, Allow) || has(list, AllowSilent) => Allowed::Allowed,
                _ if has(list, Warn) => Allowed::Warn,
                _ => Allowed::Error,
            },
            Targets::AllowListWarnRest(list) => match () {
                _ if has(list, Allow) || has(list, AllowSilent) => Allowed::Allowed,
                _ if has(list, Error) => Allowed::Error,
                _ => Allowed::Warn,
            },
            Targets::ManuallyChecked => Allowed::Allowed,
        }
    }

    /// The targets named as the ones it can be applied to: rustc's `allowed_targets`.
    pub(crate) fn allowed(self) -> impl Iterator<Item = Target> {
        let list: &'static [Policy] = match self {
            Targets::AllowList(list) | Targets::AllowListWarnRest(list) => list,
            Targets::ManuallyChecked => &[],
        };
        list.iter().filter_map(|it| match *it {
            Allow(target) => Some(target),
            _ => None,
        })
    }

    /// Whether it is an attribute of the crate only: rustc's `check_crate_level`, with
    /// whether being elsewhere is a warning (else an error).
    pub(crate) fn crate_level(self) -> Option<bool> {
        match self {
            Targets::AllowList(&[Allow(Target::Crate)]) => Some(false),
            Targets::AllowListWarnRest(&[Allow(Target::Crate)]) => Some(true),
            _ => None,
        }
    }
}

/// What a second attribute of a parser on the same node does: rustc's `OnDuplicate`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum OnDuplicate {
    /// "unused attribute".
    Warn,
    /// "unused attribute", with "this was previously accepted ...".
    WarnButFutureError,
    /// E0538-like "multiple `x` attributes": an error, `diagnostics-items`'.
    Error,
    Ignore,
}

/// How a parser takes several of its attributes on a node.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Kind {
    /// `SingleAttributeParser` / `NoArgsAttributeParser`: the first one is used.
    Single(OnDuplicate),
    /// `CombineAttributeParser`: all of them are used.
    Combine,
    /// `#[used]`: one of each of `compiler`, `linker` and none (which is `linker`).
    Used,
    /// `#[macro_use]`: one without arguments, or any with.
    MacroUse,
    /// A parser that decides itself (`#[doc]`, `#[diagnostic::..]`, stability).
    Bespoke,
}

/// rustc's `AttributeSafety`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Safety {
    Normal,
    /// Must be written `#[unsafe(..)]`, from `unsafe_since` on (an error), and before it
    /// `unsafe_attr_outside_unsafe`; `note` is `unsafe_code`'s.
    Unsafe { note: &'static str, unsafe_since: Option<Edition> },
}

/// rustc's `AttributeTemplate`.
#[derive(Clone, Copy, Debug)]
pub(crate) struct Template {
    pub(crate) word: bool,
    pub(crate) list: Option<&'static [&'static str]>,
    pub(crate) one_of: &'static [&'static str],
    pub(crate) name_value_str: Option<&'static [&'static str]>,
    pub(crate) docs: Option<&'static str>,
}

impl Template {
    /// rustc's `AttributeTemplate::suggestions` for an attribute: each form, `unsafe(..)`
    /// around it when it was written so, sorted.
    pub(crate) fn suggestions(&self, name: &str, is_unsafe: bool) -> Vec<String> {
        let (open, close) = if is_unsafe { ("unsafe(", ")") } else { ("", "") };
        // alloc: a diagnostic's text (`ill_formed`), as is each suggestion below
        let mut suggestions = Vec::new();
        if self.word {
            // alloc: as above
            suggestions.push(format!("{open}{name}{close}"));
        }
        for descr in self.list.into_iter().flatten() {
            // alloc: as above
            suggestions.push(format!("{open}{name}({descr}){close}"));
        }
        for word in self.one_of {
            // alloc: as above
            suggestions.push(format!("{open}{name}({word}){close}"));
        }
        for descr in self.name_value_str.into_iter().flatten() {
            // alloc: as above
            suggestions.push(format!("{open}{name} = \"{descr}\"{close}"));
        }
        suggestions.sort();
        suggestions
    }
}

/// rustc's `template!`.
macro_rules! template {
    (Word) => { template!(@ true, None, &[], None, None) };
    (Word, $link:literal) => { template!(@ true, None, &[], None, Some($link)) };
    (List: $descr:expr) => { template!(@ false, Some($descr), &[], None, None) };
    (List: $descr:expr, $link:literal) => { template!(@ false, Some($descr), &[], None, Some($link)) };
    (OneOf: $one_of:expr) => { template!(@ false, None, $one_of, None, None) };
    (NameValueStr: [$($descr:literal),* $(,)?]) => { template!(@ false, None, &[], Some(&[$($descr,)*]), None) };
    (NameValueStr: [$($descr:literal),* $(,)?], $link:literal) => { template!(@ false, None, &[], Some(&[$($descr,)*]), Some($link)) };
    (NameValueStr: $descr:literal) => { template!(@ false, None, &[], Some(&[$descr]), None) };
    (NameValueStr: $descr:literal, $link:literal) => { template!(@ false, None, &[], Some(&[$descr]), Some($link)) };
    (Word, List: $descr:expr) => { template!(@ true, Some($descr), &[], None, None) };
    (Word, List: $descr:expr, $link:literal) => { template!(@ true, Some($descr), &[], None, Some($link)) };
    (Word, NameValueStr: $descr:expr) => { template!(@ true, None, &[], Some(&[$descr]), None) };
    (Word, NameValueStr: $descr:expr, $link:literal) => { template!(@ true, None, &[], Some(&[$descr]), Some($link)) };
    (List: $descr1:expr, NameValueStr: $descr2:expr) => { template!(@ false, Some($descr1), &[], Some(&[$descr2]), None) };
    (List: $descr1:expr, NameValueStr: $descr2:expr, $link:literal) => { template!(@ false, Some($descr1), &[], Some(&[$descr2]), Some($link)) };
    (Word, List: $descr1:expr, NameValueStr: $descr2:expr) => { template!(@ true, Some($descr1), &[], Some(&[$descr2]), None) };
    (Word, List: $descr1:expr, NameValueStr: $descr2:expr, $link:literal) => { template!(@ true, Some($descr1), &[], Some(&[$descr2]), Some($link)) };
    (@ $word:expr, $list:expr, $one_of:expr, $name_value_str:expr, $link:expr) => {
        Template { word: $word, list: $list, one_of: $one_of, name_value_str: $name_value_str, docs: $link }
    };
}

/// One of rustc's builtin attribute parsers, for one path.
#[derive(Clone, Copy, Debug)]
pub(crate) struct Builtin {
    pub(crate) path: &'static [&'static str],
    pub(crate) kind: Kind,
    pub(crate) safety: Safety,
    pub(crate) targets: Targets,
    pub(crate) template: Template,
}

/// The parser of the attribute of path `path`, if rustc has one.
pub(crate) fn builtin(path: &[&str]) -> Option<&'static Builtin> {
    index::of(path).map(|it| &BUILTINS[it])
}

/// Every parser, sorted by path.
#[cfg(test)]
pub(crate) fn builtins() -> &'static [Builtin] {
    BUILTINS
}

